from jsonb_to_recordset($question_data$[{"id":"geo-v3-world-2b75e90e464ab574","category":"world","difficulty":1,"prompt":"Welcher Ozean ist flächenmäßig der größte?","options":["Südlicher Ozean","Indischer Ozean","Atlantischer Ozean","Pazifischer Ozean"],"correct":3,"enabled":true,"explanation":"Der Pazifik ist nach Fläche der größte der fünf Ozeane.","media":null,"provenance":{"sources":["https://oceanservice.noaa.gov/facts/biggestocean.html"],"subjectKey":"world:legacy:world-001","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-d844f08aaaf28dab","category":"world","difficulty":1,"prompt":"Auf welchem Kontinent liegt die Sahara?","options":["Südamerika","Afrika","Asien","Australien"],"correct":1,"enabled":true,"explanation":"Die Sahara erstreckt sich über Nordafrika. Sie ist eine heiße Wüste; polare Wüsten sind eine andere Kategorie.","media":null,"provenance":{"sources":["https://pubs.usgs.gov/gip/deserts/types/"],"subjectKey":"world:legacy:world-002","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-6a2b726be2020444","category":"world","difficulty":1,"prompt":"Durch welche Stadt fließt die Themse?","options":["Edinburgh","London","Belfast","Cardiff"],"correct":1,"enabled":true,"explanation":"London liegt an der Themse. Die drei anderen Optionen sind Hauptstädte anderer Landesteile des Vereinigten Königreichs.","media":null,"provenance":{"sources":["https://www.visitlondon.com/things-to-do/london-areas/river-thames"],"subjectKey":"world:legacy:world-003","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-8e003e414815e477","category":"world","difficulty":1,"prompt":"Welches Gebirge liegt zwischen Frankreich und Spanien?","options":["Kantabrisches Gebirge","Pyrenäen","Alpen","Iberisches Gebirge"],"correct":1,"enabled":true,"explanation":"Die Pyrenäen bilden das Gebirge zwischen der Iberischen Halbinsel und Frankreich. Andorra liegt ebenfalls in diesem Gebirge.","media":null,"provenance":{"sources":["https://www.jpl.nasa.gov/images/pia11162-pyrenees-mtns-spain/"],"subjectKey":"world:legacy:world-004","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-ac0ca2a5db63767f","category":"world","difficulty":1,"prompt":"In welchem Land liegt der Grand Canyon?","options":["Kanada","USA","Mexiko","Chile"],"correct":1,"enabled":true,"explanation":"Der Grand Canyon liegt im US-Bundesstaat Arizona und wurde vom Colorado River geprägt.","media":null,"provenance":{"sources":["https://www.nps.gov/grca/planyourvisit/directions.htm"],"subjectKey":"world:legacy:world-005","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-f6bba386d33862f5","category":"world","difficulty":1,"prompt":"Welches Meer liegt zwischen Europa und Nordafrika?","options":["Mittelmeer","Schwarzes Meer","Arabisches Meer","Rotes Meer"],"correct":0,"enabled":true,"explanation":"Das Mittelmeer liegt zwischen Südeuropa, Nordafrika und Vorderasien.","media":null,"provenance":{"sources":["https://www.eea.europa.eu/en/topics/in-depth/seas-and-coasts"],"subjectKey":"world:legacy:world-006","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-fe52ecf3e7a6ca27","category":"world","difficulty":1,"prompt":"Welche Insel gehört zu Italien?","options":["Korsika","Malta","Kreta","Sizilien"],"correct":3,"enabled":true,"explanation":"Sizilien gehört zu Italien. Korsika gehört zu Frankreich, Malta ist ein eigener Staat und Kreta gehört zu Griechenland.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/1427/"],"subjectKey":"world:legacy:world-007","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-e1c8e17baa4d4217","category":"world","difficulty":1,"prompt":"Welcher Fluss fließt durch Paris?","options":["Garonne","Seine","Loire","Rhône"],"correct":1,"enabled":true,"explanation":"Die Seine durchfließt Paris. Die drei anderen Optionen sind ebenfalls französische Flüsse.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/600/"],"subjectKey":"world:legacy:world-008","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-b6c228d593377c8f","category":"world","difficulty":1,"prompt":"Welches Land ist flächenmäßig größer?","options":["Vereinigte Staaten","China","Brasilien","Kanada"],"correct":3,"enabled":true,"explanation":"Unter diesen vier Ländern hat Kanada die größte Gesamtfläche. Gemeint ist die Gesamtfläche einschließlich Binnengewässern.","media":null,"provenance":{"sources":["https://github.com/mledoze/countries"],"subjectKey":"world:legacy:world-009","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-d60d5f4f5f0ec27c","category":"world","difficulty":1,"prompt":"In welchem Gebirge liegt der Mount Everest?","options":["Karakorum","Himalaya","Kunlun","Hindukusch"],"correct":1,"enabled":true,"explanation":"Der Mount Everest liegt im Himalaya an der Grenze zwischen Nepal und China.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/120/"],"subjectKey":"world:legacy:world-010","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-f5b3f12ff9bc539f","category":"world","difficulty":2,"prompt":"Welcher Fluss fließt durch Budapest?","options":["Theiß","Donau","Save","Drau"],"correct":1,"enabled":true,"explanation":"Budapest liegt an der Donau. Die drei anderen Flüsse gehören ebenfalls zum Donaueinzugsgebiet.","media":null,"provenance":{"sources":["https://www.danubecommission.org/dc/en/danube-navigation/danube-ports-map/"],"subjectKey":"world:legacy:world-011","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-15f408d66fd12514","category":"world","difficulty":2,"prompt":"Welche Wüste liegt im Norden Chiles?","options":["Atacama","Sechura","Monte","Patagonische Wüste"],"correct":0,"enabled":true,"explanation":"Die Atacama liegt an der Pazifikseite Südamerikas, insbesondere im Norden Chiles.","media":null,"provenance":{"sources":["https://astrobiology.nasa.gov/research-locations/"],"subjectKey":"world:legacy:world-012","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-131f756ad69cd7ba","category":"world","difficulty":2,"prompt":"Welche Meerenge trennt Spanien und Marokko?","options":["Straße von Gibraltar","Straße von Messina","Straße von Sizilien","Straße von Otranto"],"correct":0,"enabled":true,"explanation":"Die Straße von Gibraltar verbindet Atlantik und Mittelmeer und trennt Spanien von Marokko.","media":null,"provenance":{"sources":["https://eol.jsc.nasa.gov/Collections/EarthObservatory/articles/TheStraitofGibraltar.htm"],"subjectKey":"world:legacy:world-013","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-6d5e40ebd2ebdae3","category":"world","difficulty":2,"prompt":"Welcher See liegt zwischen Peru und Bolivien?","options":["Poopósee","Junínsee","Titicacasee","Maracaibo-See"],"correct":2,"enabled":true,"explanation":"Der Titicacasee liegt im Andenhochland auf der Grenze zwischen Peru und Bolivien.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/tentativelists/5080/"],"subjectKey":"world:legacy:world-014","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-565b5bbf8e39b738","category":"world","difficulty":2,"prompt":"Welche Insel liegt überwiegend innerhalb des Polarkreises?","options":["Neufundland","Island","Grönland","Sachalin"],"correct":2,"enabled":true,"explanation":"Der größte Teil Grönlands liegt nördlich des nördlichen Polarkreises.","media":null,"provenance":{"sources":["https://pmel.noaa.gov/arctic-zone/faq.html"],"subjectKey":"world:legacy:world-015","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-5f330f4cfa07689b","category":"world","difficulty":2,"prompt":"Welche beiden Ozeane verbindet der Panamakanal?","options":["Atlantik und Pazifik","Pazifik und Indischer Ozean","Atlantik und Indischer Ozean","Atlantik und Arktischer Ozean"],"correct":0,"enabled":true,"explanation":"Der Panamakanal verbindet über die Landenge von Panama den Atlantik mit dem Pazifik.","media":null,"provenance":{"sources":["https://pancanal.com/en/"],"subjectKey":"world:legacy:world-016","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-22317d09b7b70eeb","category":"world","difficulty":2,"prompt":"Welcher Fluss mündet in das Schwarze Meer?","options":["Wolga","Donau","Rhein","Elbe"],"correct":1,"enabled":true,"explanation":"Die Donau mündet über ihr Delta in das Schwarze Meer. Die Wolga mündet ins Kaspische Meer, Rhein und Elbe in die Nordsee.","media":null,"provenance":{"sources":["https://www.icpdr.org/"],"subjectKey":"world:legacy:world-017","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-b43dc9f3433064fd","category":"world","difficulty":2,"prompt":"In welchem Land liegt der Kilimandscharo?","options":["Tansania","Kenia","Uganda","Äthiopien"],"correct":0,"enabled":true,"explanation":"Der Kilimandscharo liegt im Nordosten Tansanias nahe der Grenze zu Kenia.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/403/"],"subjectKey":"world:legacy:world-018","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-01529dbe3a4bb693","category":"world","difficulty":2,"prompt":"Welche Insel teilen sich Haiti und die Dominikanische Republik?","options":["Kuba","Hispaniola","Jamaika","Puerto Rico"],"correct":1,"enabled":true,"explanation":"Haiti nimmt den westlichen, die Dominikanische Republik den östlichen Teil Hispaniolas ein.","media":null,"provenance":{"sources":["https://science.nasa.gov/missions/landsat/hispaniolas-changing-forests/"],"subjectKey":"world:legacy:world-019","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-881823cf812f32ae","category":"world","difficulty":2,"prompt":"Welche Wüste erstreckt sich über Teile der Mongolei und Chinas?","options":["Gobi","Karakum","Kysylkum","Taklamakan"],"correct":0,"enabled":true,"explanation":"Die Gobi erstreckt sich über Teile der südlichen Mongolei und Nordchinas.","media":null,"provenance":{"sources":["https://www.esa.int/media/envisat-radar-image-of-the-gobi-desert"],"subjectKey":"world:legacy:world-020","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-a8680b9c91915890","category":"world","difficulty":3,"prompt":"Welcher See ist der tiefste der Erde?","options":["Baikalsee","Kaspisches Meer","Tanganjikasee","Malawisee"],"correct":0,"enabled":true,"explanation":"Der Baikalsee in Russland ist mit rund 1.642 Metern der tiefste See der Erde.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/754/"],"subjectKey":"world:legacy:world-021","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-461babbc3eca83f2","category":"world","difficulty":3,"prompt":"Welcher Staat ist vollständig von Südafrika umschlossen?","options":["Simbabwe","Eswatini","Botswana","Lesotho"],"correct":3,"enabled":true,"explanation":"Lesotho ist vollständig von Südafrika umschlossen. Eswatini grenzt zusätzlich an Mosambik.","media":null,"provenance":{"sources":["https://github.com/mledoze/countries"],"subjectKey":"world:legacy:world-022","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-e109186a5548f4a2","category":"world","difficulty":3,"prompt":"Welche Meerenge trennt Alaska und Sibirien?","options":["Beringstraße","Davisstraße","Hudsonstraße","Dänemarkstraße"],"correct":0,"enabled":true,"explanation":"Die Beringstraße liegt zwischen Alaska in Nordamerika und der Tschuktschen-Halbinsel in Asien.","media":null,"provenance":{"sources":["https://www.jpl.nasa.gov/images/pia02638-misr-sights-the-bering-strait/"],"subjectKey":"world:legacy:world-023","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-6d3d2d3d7433cc4a","category":"world","difficulty":3,"prompt":"Auf welcher Insel liegt der Vulkan Ätna?","options":["Vulcano","Sizilien","Lipari","Stromboli"],"correct":1,"enabled":true,"explanation":"Der Ätna liegt auf Sizilien. Die anderen drei Optionen sind ebenfalls italienische Vulkaninseln, aber nicht der Standort des Ätna.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/1427/"],"subjectKey":"world:legacy:world-024","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-4c060991e980fca8","category":"world","difficulty":3,"prompt":"Welcher Fluss fließt durch Bagdad?","options":["Schatt al-Arab","Tigris","Diyala","Euphrat"],"correct":1,"enabled":true,"explanation":"Bagdad liegt am Tigris. Der Euphrat verläuft weiter westlich; Tigris und Euphrat vereinigen sich weiter südlich zum Schatt al-Arab.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/tentativelists/5880/"],"subjectKey":"world:legacy:world-025","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-b5dee56d74f43dfb","category":"world","difficulty":3,"prompt":"Welche Insel teilen sich Indonesien, Malaysia und Brunei?","options":["Sumatra","Sulawesi","Borneo","Neuguinea"],"correct":2,"enabled":true,"explanation":"Borneo ist zwischen Indonesien, Malaysia und Brunei aufgeteilt. Neuguinea ist zwischen Indonesien und Papua-Neuguinea geteilt.","media":null,"provenance":{"sources":["https://www.esa.int/ESA_Multimedia/Images/2025/06/Earth_from_Space_East_Kalimantan_Borneo"],"subjectKey":"world:legacy:world-026","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-c3d29f5314036432","category":"world","difficulty":3,"prompt":"Welches Gebirge trennt die Küstenebene Marokkos von Teilen der Sahara?","options":["Tibesti","Ahaggar","Rif","Atlas"],"correct":3,"enabled":true,"explanation":"Der Atlas erstreckt sich über Nordwestafrika; Teile des Gebirgssystems trennen marokkanische Küstenregionen vom Sahara-Raum.","media":null,"provenance":{"sources":["https://science.nasa.gov/earth/earth-observatory/wet-and-dry-morocco-144677/"],"subjectKey":"world:legacy:world-027","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-8b87b65a1ddccef0","category":"world","difficulty":3,"prompt":"Welcher See liegt zwischen Malawi, Mosambik und Tansania?","options":["Victoriasee","Malawisee","Tanganjikasee","Turkanasee"],"correct":1,"enabled":true,"explanation":"Der Malawisee, auch Nyassasee genannt, grenzt an Malawi, Mosambik und Tansania.","media":null,"provenance":{"sources":["https://wldb.ilec.or.jp/Display/html/3594"],"subjectKey":"world:legacy:world-028","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-9a52f0861eeb3aae","category":"world","difficulty":3,"prompt":"Welche Wüste liegt an der Atlantikküste Namibias?","options":["Namib","Sahara","Karoo","Kalahari"],"correct":0,"enabled":true,"explanation":"Die Namib liegt an der Atlantikküste des südwestlichen Afrikas, besonders in Namibia.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/1430/"],"subjectKey":"world:legacy:world-029","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-109d4ec25ea8d53d","category":"world","difficulty":3,"prompt":"Welches Meer liegt östlich der italienischen Halbinsel?","options":["Tyrrhenisches Meer","Balearen-Meer","Adriatisches Meer","Ligurisches Meer"],"correct":2,"enabled":true,"explanation":"Das Adriatische Meer liegt zwischen der italienischen Halbinsel und der Balkanhalbinsel.","media":null,"provenance":{"sources":["https://maritime-spatial-planning.ec.europa.eu/sea-basins/east-mediterranean"],"subjectKey":"world:legacy:world-030","edition":"geo-v3-2026-11"}},{"id":"geo-v3-world-30c7e5d76f1f9b95","category":"world","difficulty":2,"prompt":"In welchem Land liegt das UNESCO-gelistete Gebiet „Galápagos Islands“?","options":["Ecuador","Peru","Kolumbien","Venezuela"],"correct":0,"enabled":true,"explanation":"„Galápagos Islands“ liegt in Ecuador. Der UNESCO-Eintrag 1 bestätigt diese Länderzuordnung.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/1/"],"subjectKey":"world:nature:1","edition":"geo-v3-2026-11","iso":"EC","confusions":["CO","PE","VE"],"topic":"Naturregionen"}},{"id":"geo-v3-world-5ccb67fdce0df40e","category":"world","difficulty":3,"prompt":"In welchem Land liegt das UNESCO-gelistete Gebiet „Simien National Park“?","options":["Eritrea","Äthiopien","Kenia","Dschibuti"],"correct":1,"enabled":true,"explanation":"„Simien National Park“ liegt in Äthiopien. Der UNESCO-Eintrag 9 bestätigt diese Länderzuordnung.","media":null,"provenance":{"sources":["https://whc.unesco.org/en/list/9/"],"subjectKey":"world:nature:9","edition":"geo-v3-2026-11","iso":"ET","confusions":["DJ","KE","ER"],"topic":"Naturregionen"}},{"id":"geo-v3-world-756eaed9464de076","category":"world","difficulty":2,"prompt":"In welchem Land liegt das UNESCO-gelistete Gebiet